mapper.select:

SELECT * FROM (
  SELECT id, name, level, status, order_cnt AS orderCnt, last_active AS lastActive,
         contract_days_left AS contractDaysLeft,  AS segment FROM cb
) t WHERE t.segment IN ('CHURN_RISK','RENEW')
ORDER BY CASE WHEN t.segment='CHURN_RISK' THEN 0 WHEN t.segment='RENEW' THEN 1 ELSE 2 END,
         t.contractDaysLeft ASC, t.lastActive ASC LIMIT #{limit}


SELECT * FROM (
  SELECT id, name, level, status, order_cnt AS orderCnt, last_active AS lastActive,
         contract_days_left AS contractDaysLeft,  AS segment FROM cb
) t WHERE t.segment = #{segment}
ORDER BY t.contractDaysLeft ASC, t.lastActive DESC LIMIT #{limit}


SELECT id FROM (
  SELECT id,  AS segment FROM cb
) t WHERE t.segment = #{segment}
